SourceCode.Declaration:
abstract class TFMRequestElement
{
    TFMDocumentTypeId           documentType;
    TFMDocumentContentSubject   contentType;
    Map                         fields;
    Map                         subNodes;
    TFMDocumentDeviceId         deviceId;
    TFMDocumentMessageId        messageId;
    InventDim                   inventDim;
    InventTable                 inventTable;
    ItemId                      itemId;
    str                         rawItemID;
    TFMRequestElement           root;
    str                         refRecord;
    Name                        name;
    TFMRequestElement			contextValues;
    str                         fieldPrefix;
    TFMLogicContext             logicContext;
    XmlDocument                 origXML;
    str                         blocksToPost;
    Map     	                handledSubRequests;
    str                         stepRemovalState;


}

Method.Source:
public str replaceWithValue(str _value)
{
    return logicContext.replaceWithValue(_value, fields);

}

public Map getHandledSubRequests()
{
    if (!handledSubRequests)
    {
        handledSubRequests = new Map(Types::String, Types::String);
    }
    return handledSubRequests;
}

public TFMRequestElement getSubRequest(str _key)
{
    if (handledSubRequests && handledSubRequests.exists(_key))
    {
        return new SysDictClass(className2Id(handledSubRequests.lookup(_key))).makeObject();
    }
    return TFMXMLDeserializer::findClass(_key,'');
}

public TFMRequestElement convertToOtherRequestType(ClassName _className)
{
    return TFMXMLDeserializer::convertRequestClass(this, _className);
}

public void makeLogEntry(Description1000 _logText)
{
    TFMMessageLog::AddLogEntry(messageId, _logText);
}

public void new()
{
    fields = new Map(Types::String, Types::String);
    subNodes = new Map(Types::String, Types::Class);
    logicContext = TFMLogicContext::Construct();
}

public InventDim parmInventDim(InventDim _inventDim = inventDim)
{
    inventDim = _inventDim;

    return inventDim;
}

public XmlDocument parmOrigXML(XmlDocument _xmlDoc = origXML)
{
    origXML = _xmlDoc;
    return origXML;
}

public  name parmName(name _name = name)
{
    name = _name;
    return name;
}

public  TFMRequestElement parmRoot(TFMRequestElement _root = root)
{
    root = _root;
    return root;
}

public void addField(str _key, str _value, boolean _tryFillParmMethod = false)
{
    anytype result;
    str key = _key;

    fields.insert(key,_value);
    if (_tryFillParmMethod)
    {
        result = TFMHelper::addValueToParmMethod(key,this,_value);
        if (result)
        {
            fields.insert(key,strFmt('%1',result));
        }
    }
}

public str getFieldValue(str _key)
{
    return fields.exists(_key) ? fields.lookup(_key) : '';
}

public Map getFieldMap()
{
    return fields;
}

public List getBlocksToPost()
{
    int onlineStepCounter = 1;
    str stepBlocks = this.getFieldValue(TFMConstants::blocksToPost());
    while (fields.exists(TFMConstants::onlineStepBlocksToPost() + int2Str(onlineStepCounter)))
    {
        stepBlocks += (stepBlocks ? ';' : '')+fields.lookup(TFMConstants::onlineStepBlocksToPost() + int2Str(onlineStepCounter));
        onlineStepCounter++;
    }

    if(stepBlocks)
    {
        return strSplit(stepBlocks, ';');
    }
    return new List(Types::String);
}

public TFMDocumentTypeId parmDocumentType(TFMDocumentTypeId _documentType = documentType)
{
    documentType = _documentType;
    return documentType;
}

public TFMDocumentContentSubject ContentType()
{
    return contentType;
}

public TFMDocumentContentSubject parmContentType( TFMDocumentContentSubject _contentType = contentType)
{
    contentType = _contentType;
    return contentType;
}

public void addSubNodes(str _key, TFMRequestElement _subNode)
{
    subNodes.insert(_key, _subNode);
}

public TFMRequestElement getSubNodes(str _key)
{
    return subNodes.exists(_key) ? subNodes.lookup(_key) : null;
}

public boolean hasSubnodes()
{
    return subNodes.elements() > 0;
}

public Map getSubNodeMap()
{
    return subNodes;
}

public TFMRequestElement parmContextValues(TFMRequestElement _contextValues = contextValues)
{
    contextValues = _contextValues;
    return contextValues;
}

public TFMDocumentDeviceId parmdeviceID(TFMDocumentDeviceId _deviceId = deviceId)
{
    deviceId = _deviceId;
    return deviceId;
}

public TFMDocumentMessageId parmmessageId(TFMDocumentMessageId _messageId = messageId)
{
    messageId = _messageId;
    logicContext.parmExecutedFromDevice(true);
    return messageId;
}

public str parmReferenceIdentity(str _refRecord = refRecord)
{
    refRecord = _refRecord;
    return refRecord;
}

public Common getReferredRecord()
{
    Common      record = null;
    container   refCon;
    int64       refId;
    if (refRecord)
    {
        refCon      = strSplit(refRecord,';').pack();
        if (conLen(refCon) != 5 || !tableName2Id(conPeek(refCon ,4)))
        {
            return record;
        }
        record          = new DictTable(tableName2Id(conPeek(refCon ,4))).makeRecord();
        refId = str2Int64(conPeek(refCon ,5));
        select firstonly record where record.RecId == refid;
    }
    return record;
}

public InventTable parmInventTable(InventTable _inventTable = inventTable)
{
    inventTable = _inventTable;

    // To make sure the inventTable is available if the itemId is already provided. 
    if(itemId && !inventTable && prmIsDefault(_inventTable))
    {
        inventTable = inventTable::find(itemId);
    }
    return inventTable;
}

public ItemId parmItemId(ItemId _itemId = itemId)
{
    if (_itemId != itemId)
    {
        this.updateItemId(_itemId);
    }
    return itemId;
}

public ItemId parmItemIdBase(ItemId _itemId = itemId)
{
    if (_itemId != itemId)
    {
        this.updateItemId(_itemId);
    }

    return itemId;
}

public ItemId parmItemNumber(ItemId _itemId = itemId)
{
    if (_itemId != itemId)
    {
        this.updateItemId(_itemId);
    }
    return itemId;
}

/// <summary>
/// Updates the ItemId. Handling barcodes etc. This method is overridden by the TFMRequestInventDimElement class to set the inventdim
/// </summary>
protected void updateItemId(str _inputStr)
{
    this.parmRawItemID(_inputStr);         
    str tmpItemId = TFMHelper::string2ItemID(_inputStr, inventDim);
    itemId = tmpItemId;
}

/// <summary>
/// The raw item ID is e.g. the value of a barcode scan so it not directly an itemID.
/// </summary>
/// <returns></returns>
public str parmRawItemId(str _itemId = rawItemID)
{
    rawItemID = _itemId;
    return rawItemID;
}

public TFMLogicContext logicContext()
{
    return logicContext;
}

public str parmFieldPrefix(str _fieldPrefix = fieldPrefix)
{
    fieldPrefix = _fieldPrefix;

    return fieldPrefix;
}

public str parmStepRemovalState(str _stepRemovalState = stepRemovalState)
{
    stepRemovalState = _stepRemovalState;
    return stepRemovalState;
}
